) -> Result<CurrentModule<'a>, Refused> {
    current_module(module, modules, preparation, anchor)?;
    preparation.try_reserve_array::<CurrentModule<'_>>(
        anchor,
        1,
        "retained current module membership receipt",
    )?;
    Ok(CurrentModule {
        module,
        modules,
        owner: preparation,
    })
}

